import{_ as t,o as r,c as a,ak as o}from"./chunks/framework.B8jO0odJ.js";const h=JSON.parse('{"title":"Chainy product acceptance checklist","description":"Adopted October 23, 2026. The baseline owns decisions; the canonical GDD defines behavior. Beta: November 10 — Cryptita Plays community beta testing. Pre-final: November 21, 2","frontmatter":{"title":"Chainy product acceptance checklist","description":"Adopted October 23, 2026. The baseline owns decisions; the canonical GDD defines behavior. Beta: November 10 — Cryptita Plays community beta testing. Pre-final: November 21, 2","source":"docs/requirements/product-requirements.md","category":"Requirements","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/requirements/product-requirements.md","filePath":"content/docs/requirements/product-requirements.md"}'),s={name:"content/docs/requirements/product-requirements.md"};function n(d,e,c,i,l,p){return r(),a("div",null,[...e[0]||(e[0]=[o('<div><h1 id="chainy-product-acceptance-checklist">Chainy product acceptance checklist<a class="header-anchor" href="#chainy-product-acceptance-checklist" aria-label="Link to this section">​</a></h1><p>Adopted October 23, 2026. The <a href="/Chainy-Docs/content/docs/project-baseline.html">baseline</a> owns decisions; the <a href="/Chainy-Docs/content/docs/game-design.html">canonical GDD</a> defines behavior. Beta: <strong>November 10 — Cryptita Plays community beta testing</strong>. Pre-final: <strong>November 21, 2026</strong>.</p><p>V2-R IDs are new requirements, not renamed TD-R or CH-R requirements. The GDD&#39;s GP-01–GP-14 checks supply detailed scenarios.</p><table><thead><tr><th>ID</th><th>Scope</th><th>Required outcome and acceptance evidence</th></tr></thead><tbody><tr><td>V2-R01</td><td>CORE</td><td>A named Android build installs, opens and completes the adopted chapter offline; record revision, device and result.</td></tr><tr><td>V2-R02</td><td>CORE</td><td>Explore a compact fixed-camera 3D world, interact, open live-world dialogue and recover from pause/back/load failure. World input is disabled during dialogue.</td></tr><tr><td>V2-R03</td><td>CORE</td><td>W01–W04: select the fictional wallet/address safely, earn 12 once, review a lantern purchase of 8 + 1 fee, confirm balance 3 and unique ownership, equip without another charge, restore the workshop. Cancellation is free; repeated taps cannot duplicate rewards/purchases.</td></tr><tr><td>V2-R04</td><td>CORE</td><td>B01–B03 and demo B07: reuse the same purchase record; connect three blocks to a trusted checkpoint; reject the altered 6 versus original 8 record; restore the beacon. This is not BlockMatch or a real blockchain.</td></tr><tr><td>V2-R05</td><td>CORE</td><td>Quest states, early pickups, objectives, report-back, prerequisites and completion behave consistently. Contextual Quiz feedback explains decisions without substituting recall for gameplay.</td></tr><tr><td>V2-R06</td><td>CORE</td><td>SQLite persists profile, build/content/schema versions, quest and encyclopedia progress, balances, inventory, ledger, restoration and checkpoints; relaunch, repeat save and failed save tests preserve consistency and profile separation. No silent reset.</td></tr><tr><td>V2-R07</td><td>CORE</td><td>Quest log and encyclopedia use Discovered / Explained / Practiced / Demonstrated. Clear touch UI, instructions and save-error recovery work on named devices; these labels do not prove mastery.</td></tr><tr><td>V2-R08</td><td>CORE</td><td>Demonstrate and label the completed demo chapter honestly. Record accepted/missing scope, known issues, safe beta procedure and tested recovery. Community feedback is not automatically school-approved research.</td></tr><tr><td>V2-R09</td><td>STRETCH</td><td>A01–A03: learner labels examples, trains an actual small local classifier, revises after separate practice cases and records a first reserved-final-set test. Do not present authored responses as trained AI. Admit only after core passes.</td></tr><tr><td>V2-R10</td><td>FULL</td><td>Retain W05–W08, B04–B06/full B07, A04–A05, all twelve concepts, and standalone Wordle/BlockMatch with their own approved rules. Not November 10 acceptance blockers.</td></tr><tr><td>V2-R11</td><td>LATER SERVICE</td><td>Personal learner phones; teacher provisioning/vouchers, offline pairing, protected dashboard, collection, upload and distribution require separate design/prototype/security gates. Local demo profiles are not authenticated enrollment.</td></tr><tr><td>V2-R12</td><td>PRE-FINAL</td><td>November 21: tested functional build, honest scope statement, manuscript, actual approved evaluation/pilot-area evidence and rehearsed recovery. Confirm the school&#39;s 60% calculation and criteria; never infer it from task counts.</td></tr></tbody></table><p>Historical <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/requirements/product-requirements.html">TD-R01–10</a> and <a href="/Chainy-Docs/content/docs/archive/pre-2026-10-12/docs/requirements/product-requirements.html">CH-R01–12</a> retain their original meanings. No issue is Done merely because its specification or dates changed.</p></div>',1)])])}const m=t(s,[["render",n]]);export{h as __pageData,m as default};
